import re, os, json
files = ['/var/log/syslog','/var/log/auth.log']
email_re = re.compile(r'(?i)\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b')
# Conservative phone-ish pattern: optional country code, area code or 3 digits, then 3+4 digits; requires separators/paren or leading + to reduce random numeric false positives.
phone_re = re.compile(r'''(?x)
(?<![\w.])
(?:\+\d{1,3}[\s.-]?)?
(?:\(?\d{3}\)?[\s.-])
\d{3}[\s.-]\d{4}
(?![\w.])
''')

def redact_email(s):
    name, domain = s.split('@',1)
    n = (name[:2] + '…' + name[-1:]) if len(name) > 3 else (name[:1] + '…')
    parts = domain.split('.')
    d0 = parts[0]
    d0r = (d0[:1] + '…' + d0[-1:]) if len(d0)>2 else d0[:1]+'…'
    return n + '@' + '.'.join([d0r]+parts[1:])

def redact_phone(s):
    digits = re.sub(r'\D','',s)
    if len(digits) <= 4:
        return '…'
    return '…' + digits[-4:]

summary = {}
for path in files:
    info = {'exists': os.path.exists(path), 'readable': os.access(path, os.R_OK), 'emails': 0, 'phones': 0, 'examples': []}
    if info['exists'] and info['readable']:
        seen_ex = set()
        with open(path, 'r', errors='replace') as f:
            for ln, line in enumerate(f, 1):
                emails = email_re.findall(line)
                phones = phone_re.findall(line)
                if emails or phones:
                    info['emails'] += len(emails)
                    info['phones'] += len(phones)
                    # Add up to 10 redacted line-level examples
                    if len(info['examples']) < 10:
                        red = line.rstrip('\n')
                        for e in emails:
                            red = red.replace(e, redact_email(e))
                        for p in phones:
                            red = red.replace(p, redact_phone(p))
                        key = (ln, red)
                        if key not in seen_ex:
                            info['examples'].append({'line': ln, 'text': red[:500]})
                            seen_ex.add(key)
    summary[path] = info
print(json.dumps(summary, indent=2))
